import java.util.*;

public class Main {
    List<Integer> sortList(List<Integer> values) {
        List<Integer> result = new ArrayList<>(values);
        for (int i = 0; i < result.size(); i++) {                                   // simple O(n^2) selection sort as the naive baseline
            int minIdx = i;
            for (int j = i + 1; j < result.size(); j++) {
                if (result.get(j) < result.get(minIdx)) minIdx = j;
            }
            Collections.swap(result, i, minIdx);
        }
        return result;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        List<Integer> values = Arrays.asList(4, 2, 1, 3);
        System.out.println(solution.sortList(values));
    }
}

