using namespace std;

vector<int> sortList(vector<int>& values) {
    vector<int> result = values;
    for (int i = 0; i < (int)result.size(); i++) {                                // simple O(n^2) selection sort as the naive baseline
        int minIdx = i;
        for (int j = i + 1; j < (int)result.size(); j++) {
            if (result[j] < result[minIdx]) minIdx = j;
        }
        swap(result[i], result[minIdx]);
    }
    return result;
}

int main() {
    vector<int> values = {4, 2, 1, 3};
    vector<int> result = sortList(values);
    for (int v : result) cout << v << " ";
    cout << endl;
    return 0;
}

